import { useState } from 'react'
import { CorpLogo } from "../../asset/image"
import { Link, useLocation } from 'react-router-dom'
import { useContext } from "react";
import AppContext from "../../../Context";
interface NavbarProps {
    linkShowNavbar: string[];
}

const Navbar: React.FC<NavbarProps> = ({ linkShowNavbar }) => {

    // const { linkShowNavbar } = props;

    // Gather location information
    const location = useLocation()

    // State for opening Navbar
    const [navbar, setNavbar] = useState(false);
    const handleNav = () => {
        setNavbar(!navbar);
    }
    const { language, setLanguage } = useContext(AppContext);
    const LanguageToggle = () => {
        return (
            <div className="flex items-center bg-gray-100 rounded-full p-1 shadow-sm">
                <button
                    onClick={() => setLanguage("id")}
                    className={`px-3 py-1 text-sm rounded-full transition-all duration-200 ${language === "id"
                        ? "bg-primary-yellow-500 text-white font-semibold"
                        : "text-gray-600 hover:text-black"
                        }`}
                >
                    ID
                </button>
                <button
                    onClick={() => setLanguage("en")}
                    className={`px-3 py-1 text-sm rounded-full transition-all duration-200 ${language === "en"
                        ? "bg-primary-yellow-500 text-white font-semibold"
                        : "text-gray-600 hover:text-black"
                        }`}
                >
                    EN
                </button>
            </div>
        );
    };
    const menuText = {
        id: {
            home: "Beranda",
            certifications: "Sertifikasi",
            virtualOffice: "Virtual Office",
            intellectualProperty: "Intellectual Property",
            notary: "Notaris",
            tax: "Akuntansi Perpajakan",
            lawFirm: "Law Firm",
            advertising: "Periklanan",
            contact: "Kontak",
        },
        en: {
            home: "Home",
            certifications: "Certifications",
            virtualOffice: "Virtual Office",
            intellectualProperty: "Intellectual Property",
            notary: "Notary",
            tax: "Tax & Accounting",
            lawFirm: "Law Firm",
            advertising: "Advertising",
            contact: "Contact",
        }
    };
    const t = menuText[language as "id" | "en"];

    return (
        <div style={{ display: linkShowNavbar.some((path) => location.pathname.startsWith(path)) ? "flex" : "none", zIndex: 1, }}>
            <nav style={{ height: "80px", maxHeight: "80px", minHeight: "80px", position: "fixed", width: "100dvw", backgroundColor: "white" }} className={`${navbar ? "bg-opacity-80" : "bg-opacity-0"}`}>
                <div className="md:w-full w-full md:px-0 md:pr-5 pr-5 pt-1 mx-auto flex justify-between items-center bg-white bg-opacity-80">
                    <div className="flex justify-center gap-2 items-center">
                        <img alt='logo' src={CorpLogo} className="h-16 my-1 object-contain " />
                        {/* <h1 className="md:text-3xl text-2xl text-center font-black text-primary-blue-900 tracking-wide">
                            REGARDE
                        </h1> */}
                    </div>
                    <div className="lg:flex justify-around items-center hidden">
                        <Link className={`ml-8 text-base text-primary-black-500 ${location.pathname === '/' ? `font-bold border-b-2 border-primary-yellow-500 ` : ``}`} to="/">
                            {t.home}
                        </Link>

                        <Link className={`ml-8 text-base text-primary-black-500 ${location.pathname.startsWith('/certifications') ? `font-bold border-b-2 border-primary-yellow-500 ` : ``}`} to="/certifications">
                            {t.certifications}
                        </Link>

                        <Link className={`ml-8 text-base text-primary-black-500 ${location.pathname.startsWith('/virtual-office') ? `font-bold border-b-2 border-primary-yellow-500 ` : ``}`} to="/virtual-office">
                            {t.virtualOffice}
                        </Link>

                        <Link className={`ml-8 text-base text-primary-black-500 ${location.pathname.startsWith('/intellectual-property') ? `font-bold border-b-2 border-primary-yellow-500 ` : ``}`} to="/intellectual-property">
                            {t.intellectualProperty}
                        </Link>

                        <Link className={`ml-8 text-base text-primary-black-500 ${location.pathname.startsWith('/notary') ? `font-bold border-b-2 border-primary-yellow-500 ` : ``}`} to="/notary">
                            {t.notary}
                        </Link>

                        <Link className={`ml-8 text-base text-primary-black-500 ${location.pathname.startsWith('/tax-accounting') ? `font-bold border-b-2 border-primary-yellow-500 ` : ``}`} to="/tax-accounting">
                            {t.tax}
                        </Link>

                        <Link className={`ml-8 text-base text-primary-black-500 ${location.pathname.startsWith('/law-firm') ? `font-bold border-b-2 border-primary-yellow-500 ` : ``}`} to="/law-firm">
                            {t.lawFirm}
                        </Link>

                        <Link className={`ml-8 text-base text-primary-black-500 ${location.pathname.startsWith('/advertising') ? `font-bold border-b-2 border-primary-yellow-500 ` : ``}`} to="/advertising">
                            {t.advertising}
                        </Link>

                        <Link className={`ml-8 text-base text-primary-black-500 ${location.pathname === '/contact' ? `font-bold border-b-2 border-primary-yellow-500 ` : ``}`} to="/contact">
                            {t.contact}
                        </Link>

                        <div className="ml-6">
                            <LanguageToggle />
                        </div>
                    </div>
                    <div className="lg:hidden z-[9999] relative">
                        <button onClick={handleNav}>
                            {navbar ?
                                (<svg xmlns="http://www.w3.org/2000/svg" className="h-11 w-11 text-primary-black-500" viewBox="0 0 20 20" fill="currentColor">
                                    <path fillRule="evenodd" d="M4.293 4.293a1 1 0 011.414 0L10 8.586l4.293-4.293a1 1 0 111.414 1.414L11.414 10l4.293 4.293a1 1 0 01-1.414 1.414L10 11.414l-4.293 4.293a1 1 0 01-1.414-1.414L8.586 10 4.293 5.707a1 1 0 010-1.414z" clipRule="evenodd" />
                                </svg>)
                                :
                                (<svg xmlns="http://www.w3.org/2000/svg" className="h-11 w-11 text-primary-black-500" viewBox="0 0 20 20" fill="currentColor">
                                    <path fillRule="evenodd" d="M3 5a1 1 0 011-1h12a1 1 0 110 2H4a1 1 0 01-1-1zM3 10a1 1 0 011-1h12a1 1 0 110 2H4a1 1 0 01-1-1zM9 15a1 1 0 011-1h6a1 1 0 110 2h-6a1 1 0 01-1-1z" clipRule="evenodd" />
                                </svg>)}
                        </button>
                    </div>
                </div>
                <div className={`w-screen h-screen fixed top-0 left-0 bg-primary-black-500 bg-opacity-90 transform transition-transform duration-300 ease-in-out z-40 ${navbar ? 'translate-x-0 pointer-events-auto' : 'translate-x-full pointer-events-none'}`}>
                    <div className="font-sans bg-white bg-opacity-90">
                        <ul className="flex-col w-screen h-screen text-center pt-32 justify-around items-center text-xl tracking-wide text-white">
                            <li className="mt-6 flex justify-center">
                                <LanguageToggle />
                            </li>
                            <li onClick={handleNav} className="mr-16 py-3 font-normal hover:underline" >
                                <Link className={`ml-10 text-lg text-primary-black-500 ${location.pathname === '/' ? `font-bold border-b-2 border-primary-yellow-500 ` : ``}`} to="/">{t.home}</Link>
                            </li>
                            <li onClick={handleNav} className="mr-16 py-3 font-normal hover:underline">
                                <Link className={`ml-10 text-lg text-primary-black-500 ${location.pathname.startsWith('/certifications') ? `font-bold border-b-2 border-primary-yellow-500   ` : ``}`} to="/certifications">{t.certifications}</Link>
                            </li>
                            <li onClick={handleNav} className="mr-16 py-3 font-normal hover:underline">
                                <Link className={`ml-10 text-lg text-primary-black-500 ${location.pathname.startsWith('/virtual-office') ? `font-bold border-b-2 border-primary-yellow-500   ` : ``}`} to="/virtual-office">{t.virtualOffice}</Link>
                            </li>
                            <li onClick={handleNav} className="mr-16 py-3 font-normal hover:underline">
                                <Link className={`ml-10 text-lg text-primary-black-500 ${location.pathname.startsWith('/intellectual-property') ? `font-bold border-b-2 border-primary-yellow-500   ` : ``}`} to="/intellectual-property">{t.intellectualProperty}</Link>
                            </li>
                            <li onClick={handleNav} className="mr-16 py-3 font-normal hover:underline">
                                <Link className={`ml-10 text-lg text-primary-black-500 ${location.pathname.startsWith('/notary') ? `font-bold border-b-2 border-primary-yellow-500   ` : ``}`} to="/notary">{t.notary}</Link>
                            </li>
                            <li onClick={handleNav} className="mr-16 py-3 font-normal hover:underline">
                                <Link className={`ml-10 text-lg text-primary-black-500 ${location.pathname.startsWith('/tax-accounting') ? `font-bold border-b-2 border-primary-yellow-500   ` : ``}`} to="/tax-accounting">{t.tax}</Link>
                            </li>
                            <li onClick={handleNav} className="mr-16 py-3 font-normal hover:underline">
                                <Link className={`ml-10 text-lg text-primary-black-500 ${location.pathname.startsWith('/law-firm') ? `font-bold border-b-2 border-primary-yellow-500   ` : ``}`} to="/law-firm">{t.lawFirm}</Link>
                            </li>
                            <li onClick={handleNav} className="mr-16 py-3 font-normal hover:underline">
                                <Link className={`ml-10 text-lg text-primary-black-500 ${location.pathname.startsWith('/advertising') ? `font-bold border-b-2 border-primary-yellow-500   ` : ``}`} to="/advertising">{t.advertising}</Link>
                            </li>
                            <li onClick={handleNav} className="mr-16 py-3 font-normal hover:underline">
                                <Link className={`ml-10 text-lg text-primary-black-500 ${location.pathname === '/contact' ? `font-bold border-b-2 border-primary-yellow-500  ` : ``}`} to="/contact">{t.contact}</Link>
                            </li>
                        </ul>
                    </div>

                </div>
            </nav>
        </div>
    )
}

export default Navbar
